'use strict';
$('.main').insertAdjacentHTML('afterbegin',`<section class="panel weekly-progress" id="weeklyProgress"><div class="weekly-heading"><div><h2>每週教學進度</h2><p>各班進度直接填寫，離開格子即儲存。空白週先帶入已登記的上課紀錄，編輯後以本表內容為主。</p></div><div class="row"><button class="btn" id="weeklyCurrent">本週</button><button class="btn" id="weeklyFirst">學期開始</button><button class="btn" id="weeklySave">儲存表格</button></div></div><div class="weekly-meta"><b id="weeklyTeacher"></b><span id="weeklyStatus" role="status">請選擇老師</span></div><div class="weekly-scroll" id="weeklyScroll" tabindex="0" role="region" aria-label="每週各班進度表，可上下捲動"></div><p class="help weekly-help">淡黃色格為班級進度，藍色格為本週提醒。各週獨立保存；本表不修改原本逐堂紀錄或剩餘堂數。依畫面寬度自動排列班級，不需左右滑動。</p></section>`);
let weeklyContext='',weeklySignature='';
const weeklyDraftKey=(week,col)=>'keri-weekly-draft:'+weeklyContext+':'+week+':'+col;
function renderWeeklyProgress(){const context=(cloudOwner||'')+':'+book.active,focused=$('#weeklyScroll').contains(document.activeElement);if(context===weeklyContext&&focused)return;const groups=WeeklyProgress.columns(state),rows=WeeklyProgress.weeks(state);const signature=JSON.stringify([context,taipeiNow().date,state.classes,state.weeklyProgress,state.notes,state.exams,state.events]);if(signature===weeklySignature)return;const changed=context!==weeklyContext;weeklyContext=context;weeklySignature=signature;const scroll=$('#weeklyScroll'),top=scroll.scrollTop,current=WeeklyProgress.monday(taipeiNow().date);
 $('#weeklyTeacher').textContent=state.teacher+' · '+state.termName;
 scroll.innerHTML='<table><thead><tr><th scope="col" class="weekly-number">週次</th><th scope="col" class="weekly-dates">日期範圍</th>'+groups.map(c=>'<th scope="col">'+esc(c.name)+'</th>').join('')+'<th scope="col">本週提醒</th></tr></thead><tbody>'+rows.map(w=>{const input=(col,value,label,kind)=>{let draft=null;try{draft=localStorage.getItem(weeklyDraftKey(w.start,col));}catch{}return `<td class="${kind}"><span class="weekly-cell-label" aria-hidden="true">${esc(label.replace(/進度$/,''))}</span><textarea rows="4" maxlength="12000" data-week="${w.start}" data-weekly-col="${esc(col)}" aria-label="第${w.number}週 ${esc(label)}" spellcheck="false">${esc(draft??value)}</textarea></td>`;};return `<tr data-week-row="${w.start}" class="${w.start===current?'weekly-current':''} ${w.end<taipeiNow().date?'weekly-past':''} ${w.exam?'weekly-exam':''}"><th scope="row" class="weekly-number">第${w.number}週${w.start===current?'<small>本週</small>':''}</th><td class="weekly-dates">${shortDate(w.from)}–${shortDate(w.to)}</td>`+groups.map(c=>input(c.id,WeeklyProgress.cell(state,w.start,c),c.name+'進度','weekly-cell')).join('')+input('reminder',WeeklyProgress.reminders(state,w.start),'本週提醒','weekly-reminder')+'</tr>';}).join('')+'</tbody></table><div class="weekly-tail" aria-hidden="true"></div>';
 scroll.scrollTop=changed?0:top;scroll.scrollLeft=0;if(changed)requestAnimationFrame(()=>alignWeeklyCurrent(false));
 $('#weeklyStatus').textContent=$('#syncStatus').textContent;
}
function saveWeeklyField(field){if(!field.matches('[data-weekly-col]'))return true;const week=field.dataset.week,col=field.dataset.weeklyCol,next=structuredClone(state);next.weeklyProgress||={};const row=next.weeklyProgress[week]||={};if(col==='reminder')row.reminder=field.value;else{row.classes||={};row.classes[col]=field.value;}if(!commitPlanner(next)){$('#weeklyStatus').textContent='尚未儲存，請重試；文字草稿保留在此裝置。';return false;}try{localStorage.removeItem(weeklyDraftKey(week,col));}catch{}field.dataset.dirty='';weeklySignature='';return true;}
$('#weeklyScroll').oninput=e=>{const field=e.target;if(!field.matches('[data-weekly-col]'))return;field.dataset.dirty='true';try{localStorage.setItem(weeklyDraftKey(field.dataset.week,field.dataset.weeklyCol),field.value);$('#weeklyStatus').textContent='編輯中 · 離開格子自動儲存，或按「儲存表格」';}catch{$('#weeklyStatus').textContent='草稿保存失敗，請立即儲存或複製文字。';}};
$('#weeklyScroll').onchange=e=>saveWeeklyField(e.target);
$('#weeklySave').onclick=()=>{let ok=true;$$('#weeklyScroll textarea').forEach(field=>{let draft=null;try{draft=localStorage.getItem(weeklyDraftKey(field.dataset.week,field.dataset.weeklyCol));}catch{}if(field.dataset.dirty||draft!==null)ok=saveWeeklyField(field)&&ok;});if(ok){$('#weeklyStatus').textContent=$('#syncStatus').textContent;toast('表格已儲存，雲端結果請看同步狀態。');}};
function alignWeeklyCurrent(notify=true){const scroll=$('#weeklyScroll');if(!scroll.clientHeight)return;const head=scroll.querySelector('thead'),last=scroll.querySelector('tbody tr:last-child'),tail=scroll.querySelector('.weekly-tail');if(tail&&last)tail.style.height=Math.max(0,scroll.clientHeight-head.offsetHeight-last.offsetHeight)+'px';const row=scroll.querySelector(`[data-week-row="${WeeklyProgress.monday(taipeiNow().date)}"]`);if(row){const first=row.previousElementSibling||row;scroll.scrollTop+=first.getBoundingClientRect().top-scroll.getBoundingClientRect().top-head.offsetHeight;}else if(notify)toast('今天不在這個學期內。');}
$('#weeklyCurrent').onclick=()=>alignWeeklyCurrent();
// Teacher data renders behind the entry screen; position again once it is visible.
new MutationObserver(()=>{if(!document.body.classList.contains('auth-locked'))requestAnimationFrame(()=>alignWeeklyCurrent(false));}).observe(document.body,{attributes:true,attributeFilter:['class']});
$('#weeklyFirst').onclick=()=>$('#weeklyScroll').scrollTop=0;
new MutationObserver(()=>{if(!$('#weeklyScroll textarea[data-dirty="true"]'))$('#weeklyStatus').textContent=$('#syncStatus').textContent;}).observe($('#syncStatus'),{childList:true,subtree:true,characterData:true});
const renderBeforeWeekly=render;render=function(){renderBeforeWeekly();renderWeeklyProgress();};render();
